def solve_n4(x1, x2):
    # Step 1: Calculate x3
    numerator_x3 = x2**2 + 1
    denominator_x3 = x1 + 1

    if numerator_x3 % denominator_x3 != 0:
        return None

    x3 = (numerator_x3 // denominator_x3) - 1

    if x3 <= 0:
        return None # x3 must be a positive integer

    # Step 2: Calculate x4
    numerator_x4 = x3**2 + 1
    denominator_x4 = x2 + 1

    if numerator_x4 % denominator_x4 != 0:
        return None

    x4 = (numerator_x4 // denominator_x4) - 1

    if x4 <= 0:
        return None # x4 must be a positive integer

    return (x1, x2, x3, x4)

solutions_n4 = []
# Search space limit based on initial small case tests
for x1 in range(1, 10):
    for x2 in range(1, 10):
        solution = solve_n4(x1, x2)
        if solution:
            solutions_n4.append(solution)

print("Solutions found for N=4 (x1, x2, x3, x4) within x1, x2 < 10:")
print(solutions_n4)
